// seed: tests/seed.spec.ts
// Прод, только чтение: браузер, все не-GET запросы заблокированы.
import { test, expect } from '@playwright/test';
import { readSitemap, rawHtml, titleOf, jsonLd, listingNode, categoryPath, blockNonGet } from './ssr-seo.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('SSR и SEO публичных страниц — hydration', () => {
  test('SSR-блок скрыт к DOMContentLoaded и удалён после React; h1 и title объявления совпадают с сырым HTML #b3dc2e @desktop @prod-safe', async ({ page, request }) => {
    const sm = await readSitemap(request);
    expect(sm.listingIds.length, 'объявления в sitemap').toBeGreaterThan(0);
    const listingUrl = `/businessdetail?id=${sm.listingIds[0]}`;
    const raw = await rawHtml(request, listingUrl);
    const rawTitle = titleOf(raw.html)!;
    const name = String(listingNode(jsonLd(raw.html))?.['name'] ?? '').replace(/\s+/g, ' ').trim();
    expect(name, 'название объявления в сыром HTML').not.toBe('');

    await blockNonGet(page);
    for (const url of ['/', '/search', categoryPath(sm.categories[0]), listingUrl]) {
      await test.step(url, async () => {
        await page.goto(url, { waitUntil: 'domcontentloaded' });
        // К DOMContentLoaded SSR-блок либо уже удалён, либо скрыт (display:none).
        const shown = await page.evaluate(() => {
          const el = document.querySelector('[data-seo-body]');
          return el ? getComputedStyle(el).display !== 'none' : false;
        });
        expect(shown, 'SSR-блок виден на DOMContentLoaded').toBe(false);
        // После React — удалён из DOM.
        await expect(page.locator('[data-seo-body]')).toHaveCount(0, { timeout: 30_000 });
      });
    }

    await test.step('объявление: h1 и title после React', async () => {
      await expect(page.getByRole('heading', { level: 1, name, exact: true })).toHaveCount(1);
      await expect(page.getByRole('heading', { level: 1, name, exact: true })).toBeVisible();
      await expect(page).toHaveTitle(rawTitle);
    });
  });
});
